using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.StatisticalMechanics;
internal sealed class BoseSelectionFixedBathConstructionDocument : IScribeDocumentDefinition
{
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/StatisticalMechanics/schnellketzmerickeckardt2018bose");
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Fixed orthogonal bath realization and normalized five-mode selection in every finite dimension at least five.",
        H("Fixed bath Hamiltonian construction"),
        Blocks(
            Paragraph(Text("Following Haobo Ma and Wenlin Zhang, Five Bose-selected modes with orthogonal bath projectors (CC BY 4.0), the same two fixed coordinate projections are realized by orthonormal bath amplitude rows. The five-dimensional rows and the higher-dimensional rational certificates give actual real symmetric and complex Hermitian Hamiltonians. The occupation is normalized explicitly, and uniqueness allows competitors on arbitrary supports. This construction uses the original cubic asymmetry and signed Pfaffian proof; the matrix topology and complete scientific scope are stated in BoseSelectionFixedOrthogonalBaths.")),
            Describe.Lean(DescribeId.Create("coordinateprojector"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.coordinateProjector"),
                H("coordinateProjector"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For every finite dimension n, RCLike scalar field and coordinate r, this is the diagonal matrix with one at r and zero elsewhere. It is independent of the Hamiltonian."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("coordinateweight"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.coordinateWeight"),
                H("coordinateWeight"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For any coordinate r and vector v over an RCLike field, take the real part of the expectation of the fixed coordinate projection in v. For a unit eigenvector it is the squared modulus of its r-coordinate."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("spectralmatrix"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.spectralMatrix"),
                H("spectralMatrix"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For a unitary n by n matrix U and a real energy vector e, form U diag(ofReal(e)) U*. No ordering or simplicity is assumed in this definition."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("selected-support-eq"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.selected_support_eq"),
                H("selected_support_eq"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For any finite real skew-symmetric matrix and any two strict IsSelected solutions, their supports coincide. Neither normalization nor a preassigned support is required. The proof pairs the two nonnegative occupations against the skew matrix and rules out a missing support index by strict negativity."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("rank-four-of-fivepfaffian"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.rank_four_of_fivePfaffian"),
                H("rank_four_of_fivePfaffian"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("A real skew-symmetric five by five matrix whose last signed principal Pfaffian is nonzero has rank exactly four. Its leading four by four minor is the square of that Pfaffian; the original Pfaffian kernel prevents full rank."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("selected-normalized-unique"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.selected_normalized_unique"),
                H("selected_normalized_unique"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For a finite real skew matrix, an embedding of five indices and a normalized strict solution on that image, one nonzero last principal Pfaffian of the selected block forces every other normalized strict solution, on any support, to have that same support and occupation."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("strictfivecertificate"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.StrictFiveCertificate"),
                H("StrictFiveCertificate"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For any real n by n matrix A and embedding f of five indices, require positivity of all five signed Pfaffians of the selected principal block and strictly negative drifts outside the image for their zero extension. Skew symmetry is an additional premise of the consequence theorem."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("strictfivecertificate-selected"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.selected"),
                H("StrictFiveCertificate.selected"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For every finite real skew matrix and five-index embedding satisfying StrictFiveCertificate, normalize the zero-extended positive Pfaffian vector. It is selected, its selected block has rank four, and every normalized strict solution with arbitrary support is equal to it."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("bathf"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.bathF"),
                H("bathF"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For every n at least five and RCLike field, choose the projection onto coordinate zero. This same projection is used for every Hamiltonian of that dimension."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("bathg"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.bathG"),
                H("bathG"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For every n at least five and RCLike field, choose the projection onto coordinate one, orthogonal to the first bath."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("fixed-baths"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.fixed_baths"),
                H("fixed_baths"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For every dimension n at least five over an RCLike field, bathF and bathG are Hermitian idempotents with product zero. This helper is consumed by the strengthened Hamiltonian existence theorem, so the projection laws are part of its actual conclusion."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("fiveembedding"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.fiveEmbedding"),
                H("fiveEmbedding"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For n at least five, embed Fin 5 into Fin n by retaining the numerical index. On an increasing spectrum these are the first five levels."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("firstfive"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.firstFive"),
                H("firstFive"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For n at least five, the image of all five indices under fiveEmbedding. Its cardinality is five."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("fixedbathrates"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.fixedBathRates"),
                H("fixedBathRates"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For n at least five, any real exponent d, real energies e and unitary eigenbasis U, apply the original asym to the actual expectations of bathF and bathG in the columns of U. The original asym normalizes both weight vectors."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("exists-fixedbathhamiltonian"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/BoseSelectionFixedBathConstruction.exists_fixedBathHamiltonian"),
                H("exists_fixedBathHamiltonian"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(Source),
                Blocks(Paragraph(Text("For every natural n at least five over any RCLike field, there exists a Hermitian H with a full unitary eigenbasis and increasing simple spectrum e(i)=i+1. The same two fixed coordinate projections are Hermitian orthogonal idempotents. Their physical cubic rates have a normalized occupation on the first five levels, all five signed selected Pfaffians positive, selected rank four, and global uniqueness against every normalized IsSelected competitor on any support. Over the real and complex fields this gives actual real symmetric and complex Hermitian Hamiltonians. The five-dimensional and higher-dimensional rational occupations are distinct certificates."))), DescribeRole.Theorem))));
}
